with store_totals as (select store_id, round((100 * sum(case when status = 'COMPLETED' then 1 else 0 end)) / count(*), 1) as pct_completed, count(*) as order_count from orders where shipping_fee < 16 group by store_id) select s.id, s.opened_date, st.pct_completed, st.order_count from stores s inner join store_totals st on s.id = st.store_id where st.order_count > 6 order by order_count, s.id desc;
